import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Steady-Forcing: Balancing Spatial Persistence and Motion Continuity in Long-Horizon Nature Video Diffusion","description":"","frontmatter":{"title":"Steady-Forcing: Balancing Spatial Persistence and Motion Continuity in Long-Horizon Nature Video Diffusion","arxiv":"2606.14732","date":"2026-06-02","authors":"Matiur Rahman Minar, Seunghun Oh, GangHyeon Jeong, Unsang Park","categories":"cs.CV, cs.AI, cs.LG, cs.MM","topics":"自回归视频生成, 长视频漂移, 定机位流体","outline":[2,2]},"headers":[],"relativePath":"papers/2606.14732.md","filePath":"papers/2606.14732.md","lastUpdated":null}'),l={name:"papers/2606.14732.md"};function e(i,s,r,m,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="steady-forcing-balancing-spatial-persistence-and-motion-continuity-in-long-horizon-nature-video-diffusion" tabindex="-1">Steady-Forcing: Balancing Spatial Persistence and Motion Continuity in Long-Horizon Nature Video Diffusion <a class="header-anchor" href="#steady-forcing-balancing-spatial-persistence-and-motion-continuity-in-long-horizon-nature-video-diffusion" aria-label="Permalink to &quot;Steady-Forcing: Balancing Spatial Persistence and Motion Continuity in Long-Horizon Nature Video Diffusion&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.14732" target="_blank" rel="noreferrer">2606.14732</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-02</td></tr><tr><td><strong>作者</strong></td><td>Matiur Rahman Minar, Seunghun Oh, GangHyeon Jeong, Unsang Park（西江大学）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.LG, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>在定机位自然流体这一受控设定里，用不可变的首帧 V-Sink 锚住背景身份、用 EMA-Sink 压缩运动历史、每 21 块清一次 cache 只留锚点与最近 5 帧，再从 Wan2.1-14B 教师 + Reward-Forcing 运动先验初始化做无真值视频的定向蒸馏。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>自回归视频扩散在长 rollout 上有两个互相拉扯的失败模式。<strong>背景漂移</strong>：静止的场景元素逐步扭曲、平移，指数偏差沿 rollout 累积。<strong>运动停滞</strong>：流水、火焰、烟雾这类连续流动逐步失去动量，纹理硬化成静止的岩石或金属质感。麻烦在于，抑制第一个的手段（attention sink、更强的空间锚定）恰好会加剧第二个——模型越是紧盯着一个固定参考，就越不敢让画面动。</p><p>论文选择在<strong>定机位</strong>设定里研究这对矛盾，理由是可分性：镜头不动时，背景区域必须几何稳定，而水、雪、雨、火、烟、树叶这些动态区域必须持续运动，两个目标彼此正交，不像移动镜头那样把「场景变化」与「空间漂移」搅在一起。这个设定同时有直接用途——实时氛围媒体、程序化游戏环境、动态背景合成，都要求从固定视角持续输出连贯、有运动的画面流。</p><p>这项工作的价值有两层：一是提出了一个受控的、能把两个失败模式拆开看的实验床；二是它在结论部分给出了一个对整个领域都成立的警告——<strong>VBench 的聚合分在这个设定下是失效的</strong>。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>流式自回归一支。</strong> CausVid 建立了非对称 DMD 蒸馏流水线；Self-Forcing 用自 rollout 弥合 train-test gap 并达到 17 FPS；Rolling Forcing 用重叠帧联合去噪打断误差累积链；Causal Forcing 改进 Self-Forcing 的 ODE 初始化，论文引述其 Dynamic Degree 超出 Self-Forcing 19.3%；LongLive 用 KV-recache 支持交互式分钟级生成。这些方法各自解决了 rollout 的一部分，但它们要么以牺牲运动换取空间稳定，要么积累背景漂移。</p><p><strong>无界时长扩展一支。</strong> Infinity-RoPE 在不重训的前提下把 3D-RoPE 的硬性时间上限解开，将时间编码改写成移动的局部参考系，新块相对模型最大 horizon 索引、旧块反向旋转，并配 KV Flush 与 RoPE Cut 算子处理 prompt 响应与场景切换。它解决了长度问题，但不触碰稳定-运动权衡。</p><p><strong>运动增强蒸馏一支。</strong> Reward-Forcing 是本文最直接的基础，它给出了两件本文直接复用的东西：EMA-Sink（把逐出帧用指数滑动平均融进全局上下文），以及 Re-DMD（用视觉语言模型评分把蒸馏目标重加权到高奖励的动态区域），论文引述其达到 23.1 FPS 与 88.38% 的动态幅度提升。</p><p><strong>评测一支。</strong> VBench 的 Background Consistency 与 Dynamic Degree 是本文的主指标，但论文明确指出二者都暴露不出定机位下的长程流动衰减：Dynamic Degree 度量的是聚合运动幅度而非长程持续性，Background Consistency 不惩罚「靠冻结运动换来的稳定」。这是本文最有价值的判断之一。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从既有失败模式出发可以自然走到这个设计。</p><p>第一步是发现两类失败在移动镜头下无法分离——镜头一动，光流里既有相机运动也有流体运动，Background Consistency 的下降既可能是漂移也可能是合法的视角变化。把镜头钉死，这两项就分开了。这是一个纯粹的实验设计决策，不需要任何新方法。</p><p>第二步是承认现有工具各解一半。Infinite-Forcing 一类的 sink 能治漂移，Reward-Forcing 的 EMA-Sink 能治停滞。既然二者作用于不同的失败模式，那么把它们<strong>放进同一个全局上下文的不同槽位</strong>是最直接的做法——一个永不更新（空间），一个每步更新（动力学）。</p><p>第三步是位置编码：既然要多分钟 rollout，3D-RoPE 训练时只见过 1024 个时间索引，超出即分布外。Infinity-RoPE 的 block-relative 方案现成可用，只需额外规定两个 sink 的位置索引固定且互不重叠。</p><p>第四步是观察一个残留失败：即使有双 sink，长 rollout 仍会出现「重复纹理伪影」——局部过锐化的图案一旦形成就拒绝改变并向外蔓延。这类错误是 cache 里累积的，那就周期性地清空 cache，只留 V-Sink 与最近几帧。Infinity-RoPE 的 KV Flush 本来是响应 prompt 变化才触发的，把它改成定期触发即可。</p><p>第五步是训练。定机位自然流体是一个窄域，通用 checkpoint 在这上面不专门。但收集真值长视频代价高，于是走 DMD 蒸馏——它只需要 prompt，不需要视频。再加一个观察：从中性初始化做 DMD 会收敛到低能量子分布（画面稳定、指标好看、但流动被压死），所以初始化必须自带运动偏置——Reward-Forcing 的 checkpoint 正好是这个东西。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>空间身份与运动动量是两种寿命完全不同的信息，把它们塞进同一个注意力上下文里就必然互相挤压：锚得越死越不动，动得越多越漂。分开存——一个永不更新的首帧 KV 负责「这个场景长什么样」，一个指数衰减的压缩状态负责「刚才在怎么流」——再定期把两者之外的累积误差清掉，就能同时拿到两个通常互斥的性质。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>骨干是 Wan2.1-T2V-1.3B（flow-matching DiT），教师是冻结的 Wan2.1-T2V-14B，学生从 Reward-Forcing 的 checkpoint 初始化。以一次 60 秒生成为例：</p><ol><li><strong>全局上下文的三段结构</strong>。每步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 的注意力上下文为<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2439em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.4231em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">global</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2413em;vertical-align:-0.35em;"></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fixed</span></span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mbin mtight">+</span><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mpunct">,</span></span></span></span></span></p> V 同理。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fixed</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是首帧（Frame 0）的 K/V，永久保留、从不更新；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 EMA-Sink；后者是最近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 帧的滑窗。总显存 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mclose">)</span></span></span></span>，与 rollout 长度无关。</li><li><strong>EMA-Sink 更新</strong>。帧退出滑窗时不丢弃，而是融进压缩状态：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1583em;vertical-align:-0.317em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.317em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.99</span></span></span></span>（训练与推理一致，沿用 Reward-Forcing）。老的逐出帧被指数降权，全局记忆因此能保住长程运动上下文而不增长。</li><li><strong>位置索引</strong>。用 Infinity-RoPE 的 block-relative 编码保证索引不越界；本文的扩展是：V-Sink 永远保持时间索引 0，EMA-Sink 分配一个固定的中间索引，与滑窗互不重叠。</li><li><strong>周期性 KV Flush</strong>。每 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">purify</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">21</span></span></span></span> 块（每块 3 帧）触发一次，cache 被剪到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">anchor</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">m</span><span class="mbin mtight">+</span><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>，即 V-Sink 加最近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 个 latent 帧，中间全部丢弃。EMA-Sink 也一并清空重建——因为多步之后它可能已经装满了漂移或伪影污染的动力学。作者称 21 是平衡点：更短会在有意义的动力学积累起来之前打断运动连续性，更长则让 cache 误差固化。</li><li><strong>训练</strong>。Self-Forcing 的 DMD 循环，学生按块自回归生成并以自己的输出为条件，V-Sink / EMA-Sink / block-relative RoPE / 滑窗在训练期全部开启，与推理配置完全一致。4 步均匀去噪，6000 次迭代，batch 8，生成器学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>、critic <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">7</span></span></span></span></span></span></span></span></span></span></span></span>，8×A100 约 67 小时。</li><li><strong>无真值视频的 prompt 语料</strong>。组合采样静态场景锚点、流体类型、大气条件、全球地点，合成 21000 条 prompt，每条附加「固定三脚架视角」的相机约束。CFG 负向提示里追加领域特定的失败描述词（repetitive round textures、motion stagnation、frozen motion、static water、hardened flow 等）。</li><li><strong>评测 prompt</strong>。LLM 生成后人工筛选，与训练语料不相交，分四档：T1（5s，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathnormal">n</span><span class="mord"><span class="mrel">=</span></span><span class="mord">6</span></span></span></span>）、T2（60s，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathnormal">n</span><span class="mord"><span class="mrel">=</span></span><span class="mord">23</span></span></span></span>）、T3（120s，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathnormal">n</span><span class="mord"><span class="mrel">=</span></span><span class="mord">6</span></span></span></span>）、T4（240s，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathnormal">n</span><span class="mord"><span class="mrel">=</span></span><span class="mord">4</span></span></span></span>）。</li></ol><p>推理约 17 FPS（单卡 A100），与 Self-Forcing、Rolling Forcing 相当。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很少，核心只有 EMA 与上下文拼接两式，但有一处值得展开，因为它决定了方法的行为边界。</p><p>EMA-Sink 的递推 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 展开后是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:3.2254em;vertical-align:-1.4138em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8117em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">0</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.4138em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mspace mtight" style="margin-right:0.1952em;"></span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0691em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span></span></span></span></span></p><p>即历史逐出帧的指数加权和，等效记忆长度约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> 个 latent 帧。这解释了两件事。其一，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.99</span></span></span></span> 下 EMA-Sink 的确覆盖了远超滑窗 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 的历史。其二，也是更关键的一点：这是一个<strong>单一的、加性的</strong>压缩状态。当场景里存在多个方向不同的流动（左岸水流向下、右岸浪花向上），它们的 K/V 在求和时会部分抵消，压缩状态趋向于「平均运动」。论文的 limitations 正好承认了这个预测——EMA-Sink 的单个压缩状态无法表示大范围的相干动力学，开阔海面、宽阔河流的停滞仍未解决。这是一个从公式就能推出、并被作者实测确认的结论。</p><p>论文还形式化定义了两个失败模式：Drift 是背景静止区随 rollout 时间的渐进几何位移，可由首帧与当前帧之间的特征对齐背景位移估计；Stagnation 是动态前景区平均光流幅度的渐进衰减。这两个定义写得很清楚——但全文没有任何一处实际测量了它们，这一点在 §9 会成为主攻方向。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测协议里有一个必须先讲清楚的设定。</strong> 全部七个基线（CausVid、Self-Forcing、Infinite-Forcing、Rolling-Forcing、Reward-Forcing、LongLive、Causal-Forcing）都带 † 号，含义是：它们使用公开权重，但<strong>在本文自己的定机位推理封装下运行</strong>——V-Sink、EMA-Sink、KV Flush Loop 与 Block-Relativistic RoPE 全部套上。作者明确说这些结果应当理解为「任务适配的变体，而非原生发布分数」。这个设定同时是本文最诚实的地方和最大的解释困难，详见 §11。</p><p><strong>问题一：背景稳定性与画质。</strong> Steady-Forcing 在四个时长上的 Background Consistency / Imaging Quality 都是最高：5s 98.06/69.87，60s 95.60/71.59，120s 95.07/66.21，240s 92.57/71.27。Background Consistency 的衰减也比基线慢，与 V-Sink 的设计意图一致。Motion Smoothness、Temporal Flickering、Aesthetic Quality 大多是第一或第二。</p><p><strong>问题二：运动是否真的被保住了？</strong> 这是全文最需要审慎读的部分。Dynamic Degree 上，Steady-Forcing 在 5s 是 <strong>25.22——全表最低</strong>（Causal-Forcing 70.00、Self-Forcing 48.02、Rolling 47.06、CausVid 37.01、LongLive 34.26、Reward-Forcing 27.95、Infinite-Forcing 25.70）；在 240s 是 <strong>21.86，同样全表最低</strong>（Causal-Forcing 94.75、Rolling 55.88、Reward-Forcing 52.93、Self-Forcing 46.89、LongLive 35.80、Infinite-Forcing 26.62、CausVid 23.48）。60s 与 120s 分别是 37.43 与 37.99，处于中游。因此 VBench 平均分也不占优：5s 75.70 低于 Causal-Forcing 80.91、Rolling 77.57、Self-Forcing 76.96；60s 77.84 低于 Causal-Forcing 82.40 与 Self-Forcing 78.93；240s 74.16 低于 Causal-Forcing 81.94、Reward-Forcing 74.98、Rolling 74.96。</p><p>作者对此的回应是方法论层面的：定机位下 Dynamic Degree 把相机漂移导致的光流与真实流体运动同等奖励，一个成功抑制漂移的方法必然产生更少的背景光流，因而必然被 VBench 记为更低的 Dynamic Degree；同时该指标不惩罚纹理硬化与流动停滞。论文因此明确声明「不为通用 VBench 平均分优化」。这个论证在逻辑上成立，但它把全部举证责任推给了用户研究。</p><p><strong>问题三：人眼怎么看？</strong> 盲测对三个代表性基线（Self-Forcing、Reward-Forcing、Rolling-Forcing）做四选一：6 条 prompt × 23 名参与者 = 每个准则 138 次比较，五个准则（整体质量、静态视角稳定性、运动连续性、时间一致性、无伪影）。Steady-Forcing 五项全部第一，优势最大的是静态视角稳定性（0.746 vs 次高 0.101）与运动连续性（0.710 vs 0.116），平均 Likert 4.138 对基线的 2.283–2.572。四选一的随机基线是 0.25，而三个基线全部落在 0.072–0.123 区间。</p><p><strong>问题四：各组件的贡献。</strong> 图 6 给出分阶段定性对比：V-Sink 单独保住布局但允许停滞，EMA-Sink 单独保住运动但允许漂移，两者合并改善平衡，再加周期 Flush 减少累积伪影。<strong>这组消融完全没有数字</strong>，且各变体使用的权重并不相同——标 ∗ 的变体跑在 Infinite-Forcing 权重上，标 † 的跑在 Reward-Forcing 权重上，因此「机制差异」与「checkpoint 差异」在这张图里是混在一起的。</p><p><strong>残留问题。</strong> 作者自陈：大水体场景的停滞未完全消除，240s 仍有轻微色偏与高频背景纹理丢失；固定尺寸记忆没有召回「中段」内容的机制，每次 Flush 都会渐进丢失中段细节；flush 周期不随局部运动复杂度自适应。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：长 rollout 里空间稳定与运动持续是一对被现有 sink 类方法强行绑在一起的矛盾，定机位自然流体是把它们拆开观察的最佳受控设定；Steady-Forcing 用永不更新的首帧 V-Sink 存空间身份、用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.99</span></span></span></span> 的 EMA-Sink 存压缩运动历史、用 block-relative RoPE 解开时间索引上限、用每 21 块一次的 KV Flush 清掉尚未固化的累积伪影；训练侧从 Reward-Forcing 的运动偏置 checkpoint 出发、向 Wan2.1-14B 教师做 Self-Forcing DMD 蒸馏，配 21000 条组合生成的 prompt 与领域负向提示，全程不需要真值视频；结果是四个时长上 Background Consistency 与 Imaging Quality 全表最高、盲测五项全部大幅领先，但 Dynamic Degree 在 5s 与 240s 上是全表最低、VBench 平均分不占优；论文由此提出一个更重要的结论——通用 VBench 聚合分在定机位场景下会奖励漂移光流、不惩罚纹理硬化，需要任务特定的评测协议。</p><p><strong>三句话版</strong>：把空间身份与运动动量分别交给两个不同更新规律的 sink，再定期清 cache；在定机位自然流体上同时拿到最好的背景一致性与最强的主观运动连续性；代价是 Dynamic Degree 全表最低，作者主张这是指标的问题而非方法的问题。</p><p><strong>一句话版</strong>：稳定和流动之所以互斥，是因为它们被塞进了同一块记忆。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>Dynamic Degree 之所以低，是因为指标在惩罚「不漂移」，而不是因为模型真的动得少。</strong></p><p>整篇论文的说服力都押在这上面。如果这个解释成立，方法在两个原本互斥的目标上同时占优；如果不成立，那么 Steady-Forcing 就是又一个「用抑制运动换稳定」的方法，只不过换得更彻底——它在 5s 和 240s 上的 Dynamic Degree 是全表最低，比它自己点名批评的 Infinite-Forcing（25.70/26.62）还要低。</p><p>论文最该做而没有做的事，正是它自己在 §4 里已经定义好的：Stagnation 被形式化为「动态前景区平均光流幅度的渐进衰减」，Drift 被形式化为「静止背景区随时间的渐进几何位移」。定机位设定的全部好处就是这两个量可以分开测——用任意分割方法把流体区与背景区拆开，前者算光流幅度对 rollout 时间的斜率，后者算特征对齐位移。这需要的工程量远小于本文已经完成的训练。<strong>全文没有报告任何一个这样的数字。</strong></p><p>于是唯一的正面证据是那个用户研究。它的问题不在于结论方向，而在于它无法把「机制」与「checkpoint」分开——基线跑的是别人的权重套本文的封装，而本文的权重是专门在 21000 条定机位流体 prompt 上、从 14B 教师蒸馏出来的。人眼在这种对比里首先看到的是领域适配的画质差异（Likert 4.138 vs 2.283）。四选一里三个基线全部低于随机基线 0.25，这本身说明对比是压倒性的，而压倒性的对比恰恰最难归因。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，完全不需要重新训练。</p><ul><li><strong>底座</strong>：公开的 Self-Forcing 与 Reward-Forcing 1.3B 权重，加上作者项目页发布的 Steady-Forcing 权重。</li><li><strong>实现两个论文已定义但未测量的指标</strong>：(i) 用 SAM 或简单的运动分割把每帧拆成流体区与背景区；(ii) Stagnation 分数 = 流体区平均光流幅度对 rollout 时间的回归斜率；(iii) Drift 分数 = 背景区与首帧之间的特征对齐位移随时间的增长。</li><li><strong>数据</strong>：作者公开的 T2（60s，23 条）与 T4（240s，4 条）评测 prompt，四个方法各跑一遍。</li><li><strong>判据</strong>：若 Steady-Forcing 的 Stagnation 斜率显著优于 Reward-Forcing 与 Self-Forcing，而 Drift 也更低，则「低 Dynamic Degree 是指标假象」被证实，论文的核心主张成立；若 Stagnation 斜率并不更好，则低 Dynamic Degree 就是真实的运动抑制。</li><li><strong>附加对照</strong>：把 Steady-Forcing 的权重跑在<strong>不带任何封装</strong>的原生 Self-Forcing 推理路径上，与带封装的自己对比——这一步能第一次把 checkpoint 与记忆机制拆开。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>最强的攻击是一个归因问题，而且论文自己的实验设计已经把答案写在了表里。</strong> 全部七个基线都在<strong>本文自己的推理封装</strong>（V-Sink + EMA-Sink + KV Flush + Block-Relativistic RoPE）下评测。这意味着表 1、表 2、表 3 里的差距<strong>已经把记忆机制这一变量控制掉了</strong>——所有方法都用了同一套记忆机制。那么剩下的差异只可能来自 checkpoint 本身，即：Wan2.1-14B 教师（基线多为 1.3B 教师蒸馏）、Reward-Forcing 运动先验初始化、21000 条定机位领域 prompt、以及领域特定的负向提示。</p><p>换句话说，<strong>本文的定量与主观证据支持的是「定向蒸馏有效」，而不是「双 sink + 周期 Flush 有效」</strong>。后者的全部证据是图 6 的一组定性图，而那组图里各变体还跑在不同的基础权重上（∗ 用 Infinite-Forcing 权重、† 用 Reward-Forcing 权重）——连机制之间的相互比较都不干净。</p><p>要落成一个决定性实验：把本文的 Steady-Forcing checkpoint 分别在四种封装下评测——(a) 完整封装、(b) 去掉周期 Flush、(c) 去掉 EMA-Sink、(d) 只留原生滑窗，在同一组 T2 prompt 上报 Background Consistency、Imaging Quality 与 §10 定义的 Stagnation/Drift。若 (d) 与 (a) 差距很小，记忆机制的贡献就被证伪；若差距很大，论文的主张第一次得到定量支持。这个实验不需要训练，只需要四次推理。</p><p><strong>第二个可预测的失败条件</strong>来自 EMA-Sink 的线性结构（见 §6）：多方向相干流动会在压缩状态里互相抵消。可以直接构造 prompt——「左半画面瀑布向下、右半画面篝火烟雾向上」——预测 Steady-Forcing 在这类场景上的停滞比单向流场景更早出现。作者的 limitations 已经指出大水体场景未解决，但没有给出这个更尖锐的双向流版本。</p><p><strong>第三点关于评测规模</strong>：240s 一档只有 4 条 prompt，120s 与 5s 各 6 条。表 2 里 240s 的所有差距都建立在 4 条样本上，没有方差报告。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：本文最有价值的结论其实不是方法，而是那句警告——Dynamic Degree 奖励漂移导致的光流、不惩罚纹理硬化与流动停滞。整个领域在用一个把「运动」与「不稳定」混为一谈的标量来排名长视频方法。而本文自己也困在这个困境里：它定义了 Stagnation 和 Drift，却因为没有工具去测，只能退回到 VBench 加一个小规模用户研究。</p><p><strong>新的 framing</strong>：不要再问「这段视频动得够不够」，改问「这段视频的运动<strong>统计特性</strong>是否随时间保持不变」。自然流体（水、火、烟）在固定视角下是近似<strong>时间平稳的随机过程</strong>——瞬时画面永远在变，但光流幅度分布、时空功率谱、纹理的自相关结构在统计意义上应当稳定。停滞的本质是这个平稳性被破坏（谱能量向低频塌陷），漂移的本质是背景的空间统计发生了缓慢的非平稳位移。这把一个「运动多不多」的幅度问题，改写成一个<strong>平稳性检验</strong>问题，而后者天然区分了「合法的持续变化」与「退化」。</p><p><strong>可借鉴的相邻领域工具</strong>：动态纹理（dynamic texture）建模有半个世纪的积累，早期的 LDS 参数化与时空自回归模型给出了成熟的平稳性刻画；时间序列分析里的单位根检验与变点检测提供了现成的统计判据；湍流与流体可视化领域有针对流场谱能量分布的标准诊断。这些工具都不依赖真值视频，因此可以直接用作<strong>无参考</strong>的长视频评测。</p><p><strong>第一个实验长什么样</strong>：在现有七个基线的 240s 输出上，对流体区计算滑动窗口的时空功率谱，追踪谱质心随 rollout 时间的移动轨迹。预期结果是停滞方法的谱质心单调向低频移动，而真实自然视频的谱质心在窗口间抖动但无趋势。若这条诊断能把「Causal-Forcing 的高 Dynamic Degree」正确判定为漂移噪声、把「Steady-Forcing 的低 Dynamic Degree」正确判定为保留了流动，那么本文的核心主张就获得了独立于用户研究的证据；若判定相反，那也是一个同样重要的结论。无论哪种，这条诊断本身就能成为定机位自然流体生成缺失的那个任务特定基准。</p>',62)])])}const d=a(l,[["render",e]]);export{h as __pageData,d as default};
